import { notFound } from 'next/navigation';
import AddToCart from './add-to-cart'; // 'use client' lives in here, not here

export const revalidate = 3600;

async function getProduct(slug: string) {
  const res = await fetch(`${process.env.API_URL}/products/${slug}`, {
    // Stated per fetch. Inheriting the default is how a personalised page
    // ends up cached at the edge for everyone.
    next: { revalidate: 3600, tags: [`product:${slug}`] },
  });
  if (res.status === 404) return null;
  if (!res.ok) throw new Error(`Upstream ${res.status}`);
  return res.json() as Promise<Product>;
}

export default async function Page({ params }: { params: { slug: string } }) {
  const product = await getProduct(params.slug);
  if (!product) notFound();

  // Runs on the server. Intl is never sent to the browser.
  const price = new Intl.NumberFormat('en-BD', {
    style: 'currency',
    currency: 'BDT',
  }).format(product.priceMinor / 100);

  return (
    <main>
      <h1>{product.name}</h1>
      <p>{price}</p>
      <AddToCart sku={product.sku} max={product.stock} />
    </main>
  );
}
